/*
 * Runs the HuC6280 instruction tests generated by Mesen
 * (reference/huc6280-tests/v1/XX.json.bin, format described in transcode_json.py).
 *
 * For each test: set up the initial state, execute ONE instruction and compare
 * registers, MPRs, memory and cycle count against the expected final state.
 * Also checks that the CPU wrote to no address outside the final list.
 *
 * "Phantom" cycles (dummy bus reads) are not compared.
 *
 * Documented exceptions (see docs/hardware/cpu_notes.md):
 *  - TSB/TRB (04 0C 14 1C): Mesen computes the Z flag as (A AND memory) == 0.
 *    Geargrafx and Mednafen compute Z from the stored result; we follow them.
 *    Here the Z flag is checked against the result; the rest of P against Mesen.
 *  - TMA with operand 0: returns the last value that went through the MPR bus,
 *    hidden state the tests do not record. These tests are skipped.
 *  - Memory lists with 499+ pairs were truncated by the generator (long block
 *    transfers). If the initial list was truncated, the final memory cannot be
 *    reproduced and only registers/cycles are checked; if only the final list was
 *    truncated, the listed pairs are checked but not the search for stray writes.
 *  - Block transfers whose destination wraps around 64 KB and overwrites its
 *    own source (or the stack, when the list was truncated): if the result
 *    differs, the test is counted as skipped instead of failed.
 *
 * Usage: huc6280_tests <v1 folder> [hex opcode ...]
 * Exit code 0 = all passed.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "cpu/huc6280.h"

#define MEM_SIZE 0x200000u
#define MAX_RAM_PAIRS 500
#define TRUNCATED_PAIRS 499

typedef struct {
    uint8_t a, x, y, s, p;
    uint16_t pc;
    uint8_t mpr[8];
    int num_ram;
    int truncated;
    uint32_t ram_addr[MAX_RAM_PAIRS + 1];
    uint8_t ram_val[MAX_RAM_PAIRS + 1];
} TestState;

typedef struct {
    char name[51];
    uint32_t opcode;
    TestState initial, final;
    uint32_t num_cycles;
} Test;

/* Flat 2 MB memory and per-"generation" markers (avoids clearing 2 MB on every test). */
static uint8_t g_mem[MEM_SIZE];
static uint32_t g_written[MEM_SIZE];
static uint32_t g_expected[MEM_SIZE];
static uint32_t g_gen;
static uint32_t g_write_list[0x20000];
static uint32_t g_write_count;

static uint8_t bus_read(void *ctx, uint32_t addr)
{
    (void)ctx;
    return g_mem[addr & (MEM_SIZE - 1)];
}

static void bus_write(void *ctx, uint32_t addr, uint8_t v)
{
    (void)ctx;
    addr &= MEM_SIZE - 1;
    g_mem[addr] = v;
    if (g_written[addr] != g_gen) {
        g_written[addr] = g_gen;
        if (g_write_count < sizeof(g_write_list) / sizeof(g_write_list[0]))
            g_write_list[g_write_count++] = addr;
    }
}

/* ---- Binary format reader ---- */

typedef struct {
    const uint8_t *p, *end;
    int ok;
} Reader;

static uint32_t rd32(Reader *r)
{
    if (r->end - r->p < 4) { r->ok = 0; return 0; }
    uint32_t v = (uint32_t)r->p[0] | ((uint32_t)r->p[1] << 8) | ((uint32_t)r->p[2] << 16) | ((uint32_t)r->p[3] << 24);
    r->p += 4;
    return v;
}

static uint8_t rd8(Reader *r)
{
    if (r->end - r->p < 1) { r->ok = 0; return 0; }
    return *r->p++;
}

static void read_state(Reader *r, TestState *st)
{
    rd32(r); /* block size */
    st->a = rd8(r);
    st->x = rd8(r);
    st->y = rd8(r);
    st->s = rd8(r);
    st->p = rd8(r);
    st->pc = (uint16_t)(rd8(r) | (rd8(r) << 8));
    for (int i = 0; i < 8; i++)
        st->mpr[i] = rd8(r);
    uint32_t n = rd32(r);
    st->num_ram = 0;
    st->truncated = n >= TRUNCATED_PAIRS;
    for (uint32_t i = 0; i < n; i++) {
        uint32_t addr = rd32(r);
        uint8_t v = rd8(r);
        if (st->num_ram <= MAX_RAM_PAIRS) {
            st->ram_addr[st->num_ram] = addr;
            st->ram_val[st->num_ram] = v;
            st->num_ram++;
        }
    }
}

static int read_test(Reader *r, Test *t)
{
    const uint8_t *start = r->p;
    uint32_t full = rd32(r);
    if (!r->ok)
        return 0;
    memcpy(t->name, r->p, 50);
    t->name[50] = 0;
    r->p += 50;
    t->opcode = rd32(r);
    read_state(r, &t->initial);
    read_state(r, &t->final);
    t->num_cycles = rd32(r);
    r->p = start + full; /* skip the cycle list */
    return r->ok && r->p <= r->end;
}

/* ---- Execution ---- */

static void print_state(const char *label, uint8_t a, uint8_t x, uint8_t y, uint8_t s, uint8_t p,
                        uint16_t pc, const uint8_t *mpr)
{
    printf("    %-9s A=%02X X=%02X Y=%02X S=%02X P=%02X PC=%04X MPR=", label, a, x, y, s, p, pc);
    for (int i = 0; i < 8; i++)
        printf("%02X%s", mpr[i], i < 7 ? "," : "\n");
}

static int g_skipped;

static int is_tsb_trb(uint32_t op)
{
    return op == 0x04 || op == 0x0C || op == 0x14 || op == 0x1C;
}

static uint8_t initial_byte(const TestState *st, uint32_t addr)
{
    for (int i = 0; i < st->num_ram; i++)
        if (st->ram_addr[i] == addr)
            return st->ram_val[i];
    return 0;
}

static uint32_t test_phys(const TestState *st, uint16_t addr)
{
    return ((uint32_t)st->mpr[addr >> 13] << 13) | (addr & 0x1FFFu);
}

static int is_block_transfer(uint32_t op)
{
    return op == 0x73 || op == 0xC3 || op == 0xD3 || op == 0xE3 || op == 0xF3;
}

/* Block transfer whose destination reaches its own source bytes, or (with the
 * initial list truncated) the A/X/Y bytes saved on the stack.
 * In the first case Mesen keeps reading the old source value, which real
 * memory does not do; in the second, the result depends on unknown bytes. */
static uint32_t g_mark[MEM_SIZE];
static int g_skipped_overlap;

static int block_self_overlap(const TestState *in, uint32_t op)
{
    uint8_t b[7];
    for (int i = 0; i < 7; i++)
        b[i] = initial_byte(in, test_phys(in, (uint16_t)(in->pc + i)));
    uint16_t src = (uint16_t)(b[1] | (b[2] << 8));
    uint16_t dst = (uint16_t)(b[3] | (b[4] << 8));
    uint32_t n = (uint32_t)(b[5] | (b[6] << 8));
    if (n == 0)
        n = 0x10000;

    /* Mark: 1 = source, 2 = stack (only relevant if the initial list was truncated). */
    static uint32_t stamp;
    stamp += 4;
    for (int i = 0; i < 3; i++)
        g_mark[test_phys(in, (uint16_t)(0x2100 | (uint8_t)(in->s - i)))] = stamp + 2;
    uint16_t s = src;
    for (uint32_t i = 0; i < n; i++) {
        g_mark[test_phys(in, s)] = stamp + 1;
        int alt = (i & 1) ? -1 : 1;
        if (op == 0xC3) s--;
        else if (op == 0xF3) s = (uint16_t)(s + alt);
        else s++;
    }
    uint16_t d = dst;
    for (uint32_t i = 0; i < n; i++) {
        uint32_t m = g_mark[test_phys(in, d)];
        if (m == stamp + 1 || (m == stamp + 2 && in->truncated))
            return 1;
        int alt = (i & 1) ? -1 : 1;
        if (op == 0xC3) d--;
        else if (op == 0xE3) d = (uint16_t)(d + alt);
        else if (op != 0xD3) d++;
    }
    return 0;
}

/* Returns 1 if passed. If verbose, prints why it failed. */
static int run_test(const Test *t, int verbose)
{
    if (t->opcode == 0x43) {
        if (initial_byte(&t->initial, test_phys(&t->initial, (uint16_t)(t->initial.pc + 1))) == 0) {
            g_skipped++;
            return 1;
        }
    }

    g_gen++;
    g_write_count = 0;

    const TestState *in = &t->initial, *out = &t->final;
    for (int i = 0; i < in->num_ram; i++)
        g_mem[in->ram_addr[i] & (MEM_SIZE - 1)] = in->ram_val[i];
    for (int i = 0; i < out->num_ram; i++)
        g_expected[out->ram_addr[i] & (MEM_SIZE - 1)] = g_gen;

    HuC6280 cpu;
    memset(&cpu, 0, sizeof(cpu));
    cpu.a = in->a;
    cpu.x = in->x;
    cpu.y = in->y;
    cpu.s = in->s;
    cpu.p = in->p;
    cpu.pc = in->pc;
    memcpy(cpu.mpr, in->mpr, 8);
    cpu.read = bus_read;
    cpu.write = bus_write;

    int cycles = huc6280_step(&cpu);

    uint8_t want_p = out->p;
    if (is_tsb_trb(t->opcode) && g_write_count == 1) {
        uint8_t result = g_mem[g_write_list[0]];
        want_p = (uint8_t)((want_p & ~HU_FLAG_Z) | (result ? 0 : HU_FLAG_Z));
    }

    int ok = cpu.a == out->a && cpu.x == out->x && cpu.y == out->y && cpu.s == out->s &&
             cpu.p == want_p && cpu.pc == out->pc && memcmp(cpu.mpr, out->mpr, 8) == 0;
    int cycles_ok = (uint32_t)cycles == t->num_cycles;
    int mem_ok = 1;
    if (!in->truncated)
        for (int i = 0; i < out->num_ram; i++)
            if (g_mem[out->ram_addr[i] & (MEM_SIZE - 1)] != out->ram_val[i])
                mem_ok = 0;
    /* Writes outside the expected list (only when no list was truncated). */
    int stray = -1;
    if (!in->truncated && !out->truncated)
        for (uint32_t i = 0; i < g_write_count; i++)
            if (g_expected[g_write_list[i]] != g_gen) {
                stray = (int)g_write_list[i];
                break;
            }

    int pass = ok && cycles_ok && mem_ok && stray < 0;
    if (!pass && is_block_transfer(t->opcode) && block_self_overlap(in, t->opcode)) {
        g_skipped_overlap++;
        return 1;
    }
    if (!pass && verbose) {
        printf("  FAILED: %s\n", t->name);
        print_state("initial", in->a, in->x, in->y, in->s, in->p, in->pc, in->mpr);
        print_state("expected", out->a, out->x, out->y, out->s, want_p, out->pc, out->mpr);
        print_state("got", cpu.a, cpu.x, cpu.y, cpu.s, cpu.p, cpu.pc, cpu.mpr);
        if (!cycles_ok)
            printf("    cycles: expected %u, got %d\n", t->num_cycles, cycles);
        for (int i = 0; i < out->num_ram && mem_ok == 0; i++) {
            uint8_t got = g_mem[out->ram_addr[i] & (MEM_SIZE - 1)];
            if (got != out->ram_val[i])
                printf("    memory[%06X]: expected %02X, got %02X\n", out->ram_addr[i], out->ram_val[i], got);
        }
        if (stray >= 0)
            printf("    unexpected write at %06X\n", stray);
    }
    return pass;
}

static uint8_t *load_file(const char *path, size_t *size)
{
    FILE *f = fopen(path, "rb");
    if (!f)
        return NULL;
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t *buf = (uint8_t *)malloc((size_t)n);
    if (buf && fread(buf, 1, (size_t)n, f) != (size_t)n) {
        free(buf);
        buf = NULL;
    }
    fclose(f);
    *size = (size_t)n;
    return buf;
}

/* Returns the number of failures, or -1 if the file could not be read. */
static int run_opcode(const char *dir, int opcode, int *total)
{
    char path[1024];
    snprintf(path, sizeof(path), "%s/%02x.json.bin", dir, opcode);
    size_t size;
    uint8_t *buf = load_file(path, &size);
    if (!buf) {
        printf("ERROR: could not read %s\n", path);
        return -1;
    }

    Reader r = { buf, buf + size, 1 };
    uint32_t n = rd32(&r);
    static Test t;
    int fails = 0;
    *total = 0;
    for (uint32_t i = 0; i < n; i++) {
        if (!read_test(&r, &t)) {
            printf("ERROR: truncated file %s (test %u)\n", path, i);
            fails++;
            break;
        }
        if (t.opcode != (uint32_t)opcode) {
            printf("ERROR: unexpected opcode in %s\n", path);
            fails++;
            break;
        }
        (*total)++;
        if (!run_test(&t, fails == 0))
            fails++;
    }
    free(buf);
    return fails;
}

int main(int argc, char **argv)
{
    if (argc < 2) {
        printf("usage: %s <reference/huc6280-tests/v1 folder> [hex opcodes]\n", argv[0]);
        return 2;
    }
    const char *dir = argv[1];

    int ops[256], nops = 0;
    if (argc > 2) {
        for (int i = 2; i < argc; i++)
            ops[nops++] = (int)strtol(argv[i], NULL, 16) & 0xFF;
    } else {
        for (int i = 0; i < 256; i++)
            ops[nops++] = i;
    }

    int failed_ops = 0, total_tests = 0, total_fails = 0;
    for (int i = 0; i < nops; i++) {
        int total = 0;
        int fails = run_opcode(dir, ops[i], &total);
        if (fails < 0)
            return 2;
        total_tests += total;
        total_fails += fails;
        if (fails) {
            failed_ops++;
            printf("opcode %02X: %d of %d tests failed\n", ops[i], fails, total);
        }
    }

    printf("\n%d opcodes tested, %d tests, %d failures, %d opcodes failing\n",
           nops, total_tests, total_fails, failed_ops);
    printf("skipped: %d (TMA #0), %d (block overwriting its own source/stack)\n",
           g_skipped, g_skipped_overlap);
    printf(failed_ops ? "RESULT: FAILED\n" : "RESULT: OK\n");
    return failed_ops ? 1 : 0;
}
